// Cool tones palette for a spiral pattern
const SKY = '#1a1a2e';
const GROUND = '#16213e';
const ACCENT = '#0f3460';
const SHADOW = '#0a1929';
const HIGHLIGHT = '#2d5a80';

// Draw background
ctx.fillStyle = SKY;
ctx.fillRect(0, 0, W, H);

// Draw spiral pattern
ctx.fillStyle = ACCENT;
const centerX = W / 2;
const centerY = H / 2;
const maxRadius = Math.min(W, H) / 2 - 20;

function drawSpiral(radius, angle) {
    if (radius > maxRadius) return;

    // Calculate coordinates
    const x = centerX + Math.cos(angle) * radius;
    const y = centerY + Math.sin(angle) * radius;

    // Draw segment
    ctx.beginPath();
    ctx.moveTo(centerX, centerY);
    ctx.lineTo(x, y);
    ctx.lineWidth = 2;
    ctx.lineCap = 'round';
    ctx.strokeStyle = ACCENT;
    ctx.stroke();

    // Recursive call for next segment
    drawSpiral(radius + 5, angle + 0.3);
}

// Draw spiral
