// Add subtle gradient effect
ctx.fillStyle = HIGHLIGHT;
for (let r = 10; r <= maxRadius; r += 15) {
    ctx.beginPath();
    ctx.arc(centerX, centerY, r, 0, Math.PI * 2);
    ctx.globalAlpha = 0.1;
    ctx.fill();
    ctx.globalAlpha = 1;
}

