// Draw shell spiral
ctx.strokeStyle = '#8B4513';
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(200, 200);
let radius = 0;
const segments = 20;
const angleStep = Math.PI * 2 / segments;

for (let i = 0; i < segments; i++) {
    const angle = i * angleStep;
    const x = 200 + Math.cos(angle) * radius;
    const y = 200 + Math.sin(angle) * radius;

    if (i === 0) {
        ctx.moveTo(x, y);
    } else {
        ctx.lineTo(x, y);
    }

    radius += 5;
}

ctx.stroke();

// Draw shell details
ctx.strokeStyle = '#A0522D';
ctx.lineWidth = 1;
ctx.beginPath();
ctx.moveTo(200, 200);
radius = 0;
for (let i = 0; i < segments; i++) {
    const angle = i * angleStep;
    const x = 200 + Math.cos(angle) * radius;
    const y = 200 + Math.sin(angle) * radius;
    ctx.lineTo(x, y);
}
ctx.stroke();

